-- VERIFICACION de la etapa 6 (triggers de ventas)
-- Base de datos: u611730801_Plataforma (referencias explicitas; NO depende de USE ni de la base seleccionada en phpMyAdmin).
-- VERIFICACION DE SOLO LECTURA: no modifica nada. Cada fila debe decir OK (o ser informativa). Cualquier DETENER: no continuar.
--

SELECT 'trigger trg_can_venta_bu exacto (tiempo, evento, tabla y cuerpo normalizado)' AS verificacion, IF((SELECT COUNT(*) FROM information_schema.TRIGGERS WHERE TRIGGER_SCHEMA='u611730801_Plataforma' AND TRIGGER_NAME='trg_can_venta_bu' AND EVENT_OBJECT_TABLE='canecas_ventas' AND ACTION_TIMING='BEFORE' AND EVENT_MANIPULATION='UPDATE' AND BINARY TRIM(REGEXP_REPLACE(REPLACE(ACTION_STATEMENT, CHAR(13), ''), '[[:space:]]+', ' '))=BINARY 'BEGIN IF NOT (NEW.id <=> OLD.id) OR NOT (NEW.empresa_id <=> OLD.empresa_id) OR NOT (NEW.cliente_id <=> OLD.cliente_id) OR NOT (NEW.producto_id <=> OLD.producto_id) OR NOT (NEW.ubicacion_id <=> OLD.ubicacion_id) OR NOT (NEW.direccion_entrega <=> OLD.direccion_entrega) OR NOT (NEW.fecha_venta <=> OLD.fecha_venta) OR NOT (NEW.documento <=> OLD.documento) OR NOT (NEW.cantidad <=> OLD.cantidad) OR NOT (NEW.precio_unitario_centavos <=> OLD.precio_unitario_centavos) OR NOT (NEW.total_centavos <=> OLD.total_centavos) OR NOT (NEW.costo_centavos <=> OLD.costo_centavos) OR NOT (NEW.moneda <=> OLD.moneda) OR NOT (NEW.salida_id <=> OLD.salida_id) OR NOT (NEW.clave_operacion <=> OLD.clave_operacion) OR NOT (NEW.creado_por <=> OLD.creado_por) OR NOT (NEW.creado_en <=> OLD.creado_en) THEN SIGNAL SQLSTATE ''45000'' SET MESSAGE_TEXT = ''CANECAS_VENTA_INMUTABLE''; END IF; IF OLD.estado = ''ANULADA'' AND (NOT (NEW.estado <=> OLD.estado) OR NOT (NEW.anulada_por <=> OLD.anulada_por) OR NOT (NEW.anulada_en <=> OLD.anulada_en) OR NOT (NEW.motivo_anulacion <=> OLD.motivo_anulacion)) THEN SIGNAL SQLSTATE ''45000'' SET MESSAGE_TEXT = ''CANECAS_VENTA_ANULADA_INMUTABLE''; END IF; END')=1, 'OK', 'DETENER') AS resultado;
SELECT 'trigger trg_can_venta_bd exacto (tiempo, evento, tabla y cuerpo normalizado)' AS verificacion, IF((SELECT COUNT(*) FROM information_schema.TRIGGERS WHERE TRIGGER_SCHEMA='u611730801_Plataforma' AND TRIGGER_NAME='trg_can_venta_bd' AND EVENT_OBJECT_TABLE='canecas_ventas' AND ACTION_TIMING='BEFORE' AND EVENT_MANIPULATION='DELETE' AND BINARY TRIM(REGEXP_REPLACE(REPLACE(ACTION_STATEMENT, CHAR(13), ''), '[[:space:]]+', ' '))=BINARY 'BEGIN SIGNAL SQLSTATE ''45000'' SET MESSAGE_TEXT = ''CANECAS_VENTA_NO_ELIMINABLE''; END')=1, 'OK', 'DETENER') AS resultado;
